(function($){
    // Minimal Summernote-like plugin for simple use (supports basic toolbar and code/getter)
    function initEditor($el, options){
        var $textarea = $el; // original textarea
        $textarea.hide();
        var initial = $textarea.val() || '';
        var $wrapper = $('<div class="simple-summernote" />');
        var $toolbar = $('<div class="note-toolbar" />');
        var $editor = $('<div class="note-editable" contenteditable="true" style="min-height:200px;border:1px solid #ddd;padding:10px;border-radius:6px;background:#fff;"></div>');
        $editor.html(initial);
        // basic buttons
        var buttons = [
            {cmd:'bold', icon:'<b>B</b>'},
            {cmd:'italic', icon:'<i>I</i>'},
            {cmd:'underline', icon:'<u>U</u>'},
            {cmd:'insertUnorderedList', icon:'\u2022 list'},
            {cmd:'createLink', icon:'link'},
            {cmd:'insertImage', icon:'img'}
        ];
        buttons.forEach(function(b){
            var $btn = $('<button type="button" class="btn btn-sm btn-light mr-1">'+b.icon+'</button>');
            $btn.on('click', function(){
                if (b.cmd === 'createLink'){
                    var url = prompt('请输入链接 URL:');
                    if (url) document.execCommand('createLink', false, url);
                } else if (b.cmd === 'insertImage'){
                    var input = $('<input type="file" accept="image/*" style="display:none">');
                    input.on('change', function(e){
                        var file = this.files[0];
                        if (!file) return;
                        var reader = new FileReader();
                        reader.onload = function(ev){
                            document.execCommand('insertImage', false, ev.target.result);
                        };
                        reader.readAsDataURL(file);
                    });
                    $btn.after(input);
                    input.click();
                } else {
                    document.execCommand(b.cmd, false, null);
                }
                $editor.focus();
            });
            $toolbar.append($btn);
        });
        $wrapper.append($toolbar).append($editor);
        $textarea.after($wrapper);
        // expose methods
        $el.data('simpleSummernote', {
            code: function(html){
                if (typeof html === 'undefined') return $editor.html();
                $editor.html(html);
            },
            destroy: function(){
                $wrapper.remove();
                $textarea.show();
            }
        });
        // sync on change
        $editor.on('input', function(){
            $textarea.val($editor.html());
        });
    }

    $.fn.summernote = function(arg){
        if (typeof arg === 'object' || typeof arg === 'undefined'){
            // init
            return this.each(function(){
                var $this = $(this);
                initEditor($this, arg || {});
            });
        } else if (typeof arg === 'string'){
            // method
            var args = Array.prototype.slice.call(arguments,1);
            var $this = $(this[0]);
            var inst = $this.data('simpleSummernote');
            if (!inst) return;
            if (arg === 'code') return inst.code.apply(inst, args);
            if (arg === 'destroy') return inst.destroy.apply(inst, args);
        }
    };
})(jQuery);
